// src/path-matcher.ts
function toSegments(path) {
  return path.split("/").filter((segment) => segment.length > 0);
}
function match(pattern, pathname) {
  const patternSegments = toSegments(pattern);
  const pathSegments = toSegments(pathname);
  if (patternSegments.length !== pathSegments.length) {
    return null;
  }
  const params = {};
  for (let i = 0; i < patternSegments.length; i += 1) {
    const patternSegment = patternSegments[i];
    const pathSegment = pathSegments[i];
    if (patternSegment.startsWith(":")) {
      params[patternSegment.slice(1)] = pathSegment;
    } else if (patternSegment !== pathSegment) {
      return null;
    }
  }
  return { params };
}
function parseQuery(search) {
  const query = {};
  if (search === "" || search === "?") {
    return query;
  }
  for (const [key, value] of new URLSearchParams(search)) {
    query[key] = value;
  }
  return query;
}
function resolveRoute(registry, location) {
  const hit = registry.findByPath(location.pathname);
  if (hit === null) {
    return null;
  }
  const { menu, params } = hit;
  return {
    path: location.pathname,
    params,
    query: parseQuery(location.search ?? ""),
    pageId: menu.pageId,
    menuId: menu.id,
    activeMenu: menu.activeMenu ?? menu.id
  };
}

export {
  match,
  parseQuery,
  resolveRoute
};
